/**
 * Ramco Institute of Technology — High-Fidelity Certificate Rendering Engine
 * Implements exact reference layout: A4 landscape, pale lavender background,
 * double purple border, institutional branding, purple typography, ornamental dividers,
 * 6 signatures in 4 groups, and verifiable QR code footer.
 */

// 1. Image loader helper
function ritLoadImage(src) {
  return new Promise((resolve) => {
    if (!src) return resolve(null);
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = src;
  });
}

// 2. Direct Canvas QR Code Renderer
function ritRenderQrCode(ctx, text, x, y, size) {
  try {
    const qrLib = (typeof QRCode !== 'undefined' && QRCode.create) ? QRCode : (typeof window !== 'undefined' && window.QRCode && window.QRCode.create ? window.QRCode : null);
    if (!qrLib) {
      console.warn('QRCode library not available for direct render');
      return false;
    }
    const qr = qrLib.create(text, { errorCorrectionLevel: 'M' });
    const numModules = qr.modules.size;
    const margin = 1;
    const totalModules = numModules + margin * 2;
    const cellSize = size / totalModules;

    // Crisp white background card
    ctx.save();
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(x - 4, y - 4, size + 8, size + 24);

    // Render dark modules
    ctx.fillStyle = '#1E1B4B';
    for (let r = 0; r < numModules; r++) {
      for (let c = 0; c < numModules; c++) {
        if (qr.modules.get(r, c)) {
          ctx.fillRect(
            Math.round(x + (c + margin) * cellSize),
            Math.round(y + (r + margin) * cellSize),
            Math.ceil(cellSize),
            Math.ceil(cellSize)
          );
        }
      }
    }

    // QR Caption
    ctx.fillStyle = '#581C87';
    ctx.font = 'bold 11px "Times New Roman", Georgia, serif';
    ctx.textAlign = 'center';
    ctx.fillText('SCAN TO VERIFY', x + size / 2, y + size + 14);
    ctx.restore();
    return true;
  } catch (err) {
    console.warn('Direct QR render exception:', err);
    return false;
  }
}

// 3. Centralized Signature Asset Mapper & Configuration Warning
function getSignatoryAsset(keyOrObj) {
  if (!keyOrObj) return null;
  if (typeof keyOrObj === 'object') {
    if (keyOrObj.sig) return getSignatoryAsset(keyOrObj.sig);
    if (keyOrObj.name) return getSignatoryAsset(keyOrObj.name);
  }
  const str = String(keyOrObj).toLowerCase().trim();
  if (str.startsWith('data:image/')) return keyOrObj;

  // In Node.js environment: read directly from frontend/signature/*.png on disk
  // This guarantees that any manual file alteration by the user immediately takes effect!
  if (typeof window === 'undefined' && typeof require !== 'undefined') {
    try {
      const fs = require('fs');
      const path = require('path');
      let diskFile = null;
      if (str.includes('jeya') || str.includes('sundari') || str.includes('faculty_coordinator')) diskFile = 'jeyasundari.png';
      else if (str.includes('rekha')) diskFile = 'rekha.png';
      else if (str.includes('ramakrishnan')) diskFile = 'ramakrishnan.png';
      else if (str.includes('kesavaraja') || str.includes('convenor')) diskFile = 'kesavaraja.png';
      else if (str.includes('rajakarunakaran') || str.includes('rajakumaran') || str.includes('patron')) diskFile = 'rajakarunakaran.png';
      else if (str.includes('ganesan') || str.includes('chief')) diskFile = 'ganesan.png';

      if (diskFile) {
        const candidates = [
          path.join(__dirname, 'signature', diskFile),
          path.join(__dirname, '..', 'frontend', 'signature', diskFile),
          path.join(process.cwd(), 'frontend', 'signature', diskFile),
          path.join(process.cwd(), 'signature', diskFile)
        ];
        for (const cand of candidates) {
          if (fs.existsSync(cand)) {
            const buf = fs.readFileSync(cand);
            return `data:image/png;base64,${buf.toString('base64')}`;
          }
        }
      }
    } catch (e) {
      console.warn('Node signature file read warning:', e);
    }
  }

  const sigMap = (typeof window !== 'undefined' && window.CERT_ASSETS && window.CERT_ASSETS.SIGNATURES)
    ? window.CERT_ASSETS.SIGNATURES
    : (typeof CERT_ASSETS !== 'undefined' ? CERT_ASSETS.SIGNATURES : {});

  // High-fidelity keyword matching for official CSBS signatories
  if (str.includes('jeya') || str.includes('sundari') || str.includes('faculty_coordinator')) {
    return sigMap.jeyasundari || 'signature/jeyasundari.png';
  }
  if (str.includes('rekha')) {
    return sigMap.rekha || 'signature/rekha.png';
  }
  if (str.includes('ramakrishnan')) {
    return sigMap.ramakrishnan || 'signature/ramakrishnan.png';
  }
  if (str.includes('kesavaraja') || str.includes('convenor')) {
    return sigMap.kesavaraja || 'signature/kesavaraja.png';
  }
  if (str.includes('rajakarunakaran') || str.includes('rajakumaran') || str.includes('patron')) {
    return sigMap.rajakarunakaran || sigMap.rajakumaran || 'signature/rajakarunakaran.png';
  }
  if (str.includes('ganesan') || str.includes('chief')) {
    return sigMap.ganesan || 'signature/ganesan.png';
  }

  if (sigMap[str]) return sigMap[str];

  console.warn(`[Configuration Warning] Required signature asset for "${keyOrObj}" is missing from repository assets. Please verify approved signatory configuration.`);
  return null;
}

// 4. Vector Ornamental Arabesque Divider for Canvas
function drawCanvasArabesque(ctx, cx, cy, width = 240) {
  const purple = '#581C87';
  const gold = '#C59B27';
  ctx.save();

  // Helper for canvas diamond
  function drawDiamond(x, y, rx, ry, fillStyle, strokeStyle, lineWidth = 1) {
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    if (fillStyle) {
      ctx.fillStyle = fillStyle;
      ctx.fill();
    }
    if (strokeStyle) {
      ctx.strokeStyle = strokeStyle;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Outer center purple diamond
  drawDiamond(cx, cy, 14, 18, null, purple, 2.4);

  // Center purple dot
  ctx.fillStyle = purple;
  ctx.beginPath();
  ctx.arc(cx, cy, 3.6, 0, Math.PI * 2);
  ctx.fill();

  // Flanking gold diamonds
  drawDiamond(cx - 30, cy, 11, 11, gold, gold);
  drawDiamond(cx + 30, cy, 11, 11, gold, gold);

  // Horizontal purple lines
  ctx.strokeStyle = purple;
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.moveTo(cx - 250, cy);
  ctx.lineTo(cx - 48, cy);
  ctx.moveTo(cx + 48, cy);
  ctx.lineTo(cx + 250, cy);
  ctx.stroke();

  // Terminal gold dots
  ctx.fillStyle = gold;
  ctx.beginPath();
  ctx.arc(cx - 250, cy, 4.4, 0, Math.PI * 2);
  ctx.arc(cx + 250, cy, 4.4, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

// Helper: Sanitize unicode quotes and en-dashes for jsPDF compatibility
function sanitizePdfText(str) {
  if (!str) return '';
  return String(str)
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2013\u2014]/g, '-');
}

// 5. Canvas Renderer matching the reference design
async function drawRitCertificate(canvas, certData = {}, options = {}) {
  const ctx = canvas.getContext('2d');
  const width = canvas.width || 2000;
  const height = canvas.height || 1414;
  canvas.width = width;
  canvas.height = height;

  // 1. Background
  const bgImgSrc = certData.background || (typeof window !== 'undefined' && window.CERT_ASSETS ? window.CERT_ASSETS.BACKGROUND_IMAGE || window.CERT_ASSETS.BACKGROUND_SVG : null) || 'certificate_background.png';
  const bgImg = await ritLoadImage(bgImgSrc);
  if (bgImg) {
    ctx.drawImage(bgImg, 0, 0, width, height);
  } else {
    ctx.fillStyle = '#FBF8FF';
    ctx.fillRect(0, 0, width, height);
    ctx.strokeStyle = '#581C87';
    ctx.lineWidth = 4;
    ctx.strokeRect(44, 32, width - 88, height - 64);
    ctx.strokeStyle = '#C59B27';
    ctx.lineWidth = 2;
    ctx.strokeRect(58, 46, width - 116, height - 92);
  }

  // 2. Approved RIT Shield Logo at Upper Left
  const ritLogoSrc = certData.rit_logo || (typeof window !== 'undefined' && window.CERT_ASSETS ? window.CERT_ASSETS.RIT_LOGO : null) || 'rit_logo.png';
  const ritImg = await ritLoadImage(ritLogoSrc);
  if (ritImg) {
    ctx.drawImage(ritImg, 114, 94, 168, 168);
  }

  // 3. Centered Institutional Heading
  ctx.textAlign = 'center';
  ctx.font = 'bold 36px "Times New Roman", Georgia, serif';
  ctx.fillStyle = '#1A1A40';
  ctx.fillText('RAMCO INSTITUTE OF TECHNOLOGY', width / 2, 118);

  ctx.font = 'normal 19px "Times New Roman", Georgia, serif';
  ctx.fillStyle = '#B91C1C';
  ctx.fillText('(An Autonomous Institution)', width / 2, 148);

  ctx.font = 'normal 16px "Times New Roman", Georgia, serif';
  ctx.fillText('Approved by AICTE, New Delhi & Affiliated to Anna University', width / 2, 174);

  ctx.font = 'bold 16px "Times New Roman", Georgia, serif';
  ctx.fillStyle = '#111827';
  ctx.fillText("NAAC Accredited with 'A+' Grade & An ISO 9001: 2015 Certified Institution", width / 2, 199);

  ctx.font = 'normal 16px "Times New Roman", Georgia, serif';
  ctx.fillStyle = '#B91C1C';
  ctx.fillText('NBA Accredited UG Programs: CSE, EEE, and MECH.', width / 2, 224);

  // 4. CSBS Department Logo Centered Beneath Institutional Heading
  const csbsLogoSrc = certData.csbs_logo || (typeof window !== 'undefined' && window.CERT_ASSETS ? window.CERT_ASSETS.CSBS_LOGO : null) || 'certificate_logo/csbs_logo_clean.png';
  const csbsImg = await ritLoadImage(csbsLogoSrc);
  if (csbsImg) {
    const csbsW = 323;
    const csbsH = Math.round(csbsW / 4.251);
    const csbsX = (width - csbsW) / 2;
    const csbsY = 241;
    ctx.drawImage(csbsImg, csbsX, csbsY, csbsW, csbsH);
  }

  // 5. Certificate Heading
  ctx.font = 'bold 44px "Times New Roman", Georgia, serif';
  ctx.fillStyle = '#4A154B';
  ctx.fillText(certData.certificate_title || 'CERTIFICATE OF PARTICIPATION', width / 2, 367);

  // Ornamental floral divider with gold & purple diamonds
  drawCanvasArabesque(ctx, width / 2, 394, 250);

  // 6. Recipient Section
  ctx.font = 'normal 23px "Times New Roman", Georgia, serif';
  ctx.fillStyle = '#1F2937';
  ctx.fillText(certData.preamble || 'This certificate is presented to', width / 2, 444);

  // Recipient Participant Name with auto-scaling
  const participantName = certData.participant_name || certData.student_name || 'Keerthana Mohan';
  let nameFontSize = 56;
  if (participantName.length > 28) nameFontSize = 46;
  if (participantName.length > 38) nameFontSize = 36;
  ctx.font = `bold italic ${nameFontSize}px "Times New Roman", Georgia, serif`;
  ctx.fillStyle = '#3B0764';
  ctx.fillText(participantName, width / 2, 518);

  // Ornamental floral divider below recipient name
  drawCanvasArabesque(ctx, width / 2, 548, 250);

  // 7. Event Description Paragraph
  const pY = 598;
  const lineSpacing = 35;
  ctx.font = 'normal 20px "Times New Roman", Georgia, serif';
  ctx.fillStyle = '#1F2937';

  let collStr = (certData.college_name || 'Ramco Institute of Technology').replace(/,\s*Rajapalayam.*$/i, '').trim();
  let evName = (certData.event_name || 'Emerging Blockchain Technologies – Architectures, Applications and Research Perspectives').replace(/^["“”]/, '').replace(/["“”]$/, '').trim();
  let progTitle = certData.programme_title || 'One Week Short-Term Training Programme (STTP)';
  let deptStr = certData.department || 'Department of Computer Science and Business Systems';
  let datesStr = (certData.programme_dates || 'October 12, 2026, to October 18, 2026').replace(/\.$/, '') + '.';

  ctx.fillText(`for active and enthusiastic participation in the ${progTitle} on`, width / 2, pY);
  ctx.font = 'bold 21px "Times New Roman", Georgia, serif';
  ctx.fillStyle = '#4A154B';
  ctx.fillText(`“${evName}”, organized`, width / 2, pY + lineSpacing);
  ctx.fillText(`by the ${deptStr} at ${collStr},`, width / 2, pY + lineSpacing * 2);
  ctx.fillText(`Rajapalayam from ${datesStr}`, width / 2, pY + lineSpacing * 3);

  // 8. Signatures: Exactly Four Groups with Vertical Gold Separators
  const sigLineY = 928;
  const purple = '#581C87';
  const gold = '#C59B27';

  const sigCenters = [215, 444, 673, 963, 1293, 1623];
  const sigConfigs = [
    { name: certData.signatory_1_name || 'Dr. M. Jeya Sundari', key: 'jeyasundari' },
    { name: certData.signatory_2_name || 'M. Rekha', key: 'rekha' },
    { name: certData.signatory_3_name || 'M. Ramakrishnan', key: 'ramakrishnan' },
    { name: certData.signatory_4_name || 'Dr. D. Kesavaraja', role: 'Convenor', key: 'kesavaraja' },
    { name: certData.signatory_5_name || 'Dr. S. Rajakarunakaran', role: 'Patron', key: 'rajakarunakaran' },
    { name: certData.signatory_6_name || 'Dr. L. Ganesan', role: 'Chief Patron', key: 'ganesan' }
  ];

  for (let i = 0; i < 6; i++) {
    const cx = sigCenters[i];
    const item = sigConfigs[i];
    const sigSrc = getSignatoryAsset(certData[`signatory_${i + 1}_sig`] || item.key);
    const sigImg = await ritLoadImage(sigSrc);
    if (sigImg) {
      const maxW = 175;
      const maxH = 80;
      let w = maxW;
      let h = maxH;
      if (sigImg.width && sigImg.height) {
        const aspect = sigImg.width / sigImg.height;
        if (maxW / aspect <= maxH) {
          h = maxW / aspect;
        } else {
          w = maxH * aspect;
        }
      }
      ctx.drawImage(sigImg, cx - w / 2, sigLineY - h - 6, w, h);
    }

    // Baseline Line
    ctx.strokeStyle = purple;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(cx - 88, sigLineY);
    ctx.lineTo(cx + 88, sigLineY);
    ctx.stroke();

    // Name
    ctx.font = 'bold 18px "Times New Roman", Georgia, serif';
    ctx.fillStyle = '#111827';
    ctx.textAlign = 'center';
    ctx.fillText(item.name, cx, sigLineY + 30);
  }

  // Vertical Gold Separators
  function drawCanvasVerticalSep(x) {
    ctx.strokeStyle = gold;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(x, 888);
    ctx.lineTo(x, 1002);
    ctx.stroke();
  }

  // Group 1 label: "Faculty Coordinators" (centered beneath the 3 coordinators)
  ctx.font = 'bold 20px "Times New Roman", Georgia, serif';
  ctx.fillStyle = '#4A154B';
  ctx.fillText('Faculty Coordinators', 444, sigLineY + 80);

  // Separator 1
  drawCanvasVerticalSep(801);

  // Group 2 label: "Convenor"
  ctx.fillText('Convenor', 963, sigLineY + 64);

  // Separator 2
  drawCanvasVerticalSep(1131);

  // Group 3 label: "Patron"
  ctx.fillText('Patron', 1293, sigLineY + 64);

  // Separator 3
  drawCanvasVerticalSep(1461);

  // Group 4 label: "Chief Patron"
  ctx.fillText('Chief Patron', 1623, sigLineY + 64);

  // Separator 4
  drawCanvasVerticalSep(1784);

  // 9. QR Code at Bottom-Right
  const certId = certData.certificate_number || certData.certificate_id || 'RIT-STTP-2026-0001';
  const qrTarget = certData.verification_url || ((typeof window !== 'undefined' && window.location && window.location.origin) ? window.location.origin : 'https://rit-csbs-portal.vercel.app') + '/verify-certificate.html?id=' + encodeURIComponent(certId);
  ritRenderQrCode(ctx, qrTarget, 1818, 1015, 128);

  // 10. Unique Certificate ID in Centered Rounded Pill with Flanking Gold Lines & Diamonds
  const pillW = 458;
  const pillH = 46;
  const pillX = (width - pillW) / 2;
  const pillY = 1165;
  const pillR = 23;

  // Flanking gold lines
  const lineLen = 215;
  const leftStart = pillX - lineLen - 26;
  const leftEnd = pillX - 20;
  const rightStart = pillX + pillW + 20;
  const rightEnd = pillX + pillW + lineLen + 26;
  const midY = pillY + pillH / 2;

  ctx.strokeStyle = gold;
  ctx.fillStyle = gold;
  ctx.lineWidth = 2.4;

  // Left line + dots + diamond
  ctx.beginPath();
  ctx.moveTo(leftStart, midY);
  ctx.lineTo(leftEnd, midY);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(leftStart, midY, 3.6, 0, Math.PI * 2);
  ctx.fill();
  const lMid = (leftStart + leftEnd) / 2;
  ctx.beginPath();
  ctx.moveTo(lMid, midY - 8);
  ctx.lineTo(lMid + 8, midY);
  ctx.lineTo(lMid, midY + 8);
  ctx.lineTo(lMid - 8, midY);
  ctx.closePath();
  ctx.fill();

  // Right line + dots + diamond
  ctx.beginPath();
  ctx.moveTo(rightStart, midY);
  ctx.lineTo(rightEnd, midY);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(rightEnd, midY, 3.6, 0, Math.PI * 2);
  ctx.fill();
  const rMid = (rightStart + rightEnd) / 2;
  ctx.beginPath();
  ctx.moveTo(rMid, midY - 8);
  ctx.lineTo(rMid + 8, midY);
  ctx.lineTo(rMid, midY + 8);
  ctx.lineTo(rMid - 8, midY);
  ctx.closePath();
  ctx.fill();

  // Rounded Pill
  ctx.fillStyle = '#FFFFFF';
  ctx.strokeStyle = gold;
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.roundRect(pillX, pillY, pillW, pillH, pillR);
  ctx.fill();
  ctx.stroke();

  // Text inside pill
  ctx.font = 'bold 19px "Times New Roman", Georgia, serif';
  ctx.fillStyle = '#1A1A40';
  ctx.textAlign = 'center';
  ctx.fillText('Certificate ID: ' + certId, width / 2, pillY + 30);

  return canvas;
}

// 6. Universal jsPDF Generator matching exact reference layout
async function createCertificatePdf(certData = {}) {
  let jsPDFClass = null;
  if (typeof window !== 'undefined' && window.jspdf && window.jspdf.jsPDF) {
    jsPDFClass = window.jspdf.jsPDF;
  } else if (typeof require !== 'undefined') {
    try {
      const mod = require('jspdf');
      jsPDFClass = mod.jsPDF || mod;
    } catch (e) {}
  }
  if (!jsPDFClass) {
    throw new Error('jsPDF library not available in runtime.');
  }

  const doc = new jsPDFClass({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a4'
  });

  const pageWidth = 297;
  const pageHeight = 210;

  // 1. Decorative Background Asset
  const bgData = certData.background || (typeof window !== 'undefined' && window.CERT_ASSETS ? window.CERT_ASSETS.BACKGROUND_IMAGE || window.CERT_ASSETS.BACKGROUND_SVG : null);
  if (bgData) {
    try {
      doc.addImage(bgData, 'PNG', 0, 0, pageWidth, pageHeight);
    } catch (e) {
      console.warn('BG embed warning:', e);
    }
  } else {
    doc.setFillColor(251, 248, 255);
    doc.rect(0, 0, pageWidth, pageHeight, 'F');
    doc.setDrawColor(88, 28, 135);
    doc.setLineWidth(0.8);
    doc.rect(6.5, 5.0, pageWidth - 13, pageHeight - 10);
    doc.setDrawColor(197, 155, 39);
    doc.setLineWidth(0.35);
    doc.rect(8.8, 7.3, pageWidth - 17.6, pageHeight - 14.6);
  }

  // 2. Approved RIT College Shield Logo at Upper Left
  const ritLogo = certData.rit_logo || (typeof window !== 'undefined' && window.CERT_ASSETS ? window.CERT_ASSETS.RIT_LOGO : null);
  if (ritLogo) {
    try {
      doc.addImage(ritLogo, 'PNG', 17, 14, 25, 25);
    } catch (e) {
      console.warn('RIT logo embed warning:', e);
    }
  }

  // 3. Centered Institutional Heading Area
  doc.setFont('times', 'bold');
  doc.setFontSize(16.5);
  doc.setTextColor(26, 26, 64);
  doc.text('RAMCO INSTITUTE OF TECHNOLOGY', pageWidth / 2, 17.5, { align: 'center' });

  doc.setFont('times', 'normal');
  doc.setFontSize(8.5);
  doc.setTextColor(185, 28, 28);
  doc.text('(An Autonomous Institution)', pageWidth / 2, 22.0, { align: 'center' });

  doc.setFontSize(7.2);
  doc.text('Approved by AICTE, New Delhi & Affiliated to Anna University', pageWidth / 2, 25.8, { align: 'center' });

  doc.setFont('times', 'bold');
  doc.setFontSize(7.2);
  doc.setTextColor(17, 24, 39);
  doc.text("NAAC Accredited with 'A+' Grade & An ISO 9001: 2015 Certified Institution", pageWidth / 2, 29.5, { align: 'center' });

  doc.setFont('times', 'normal');
  doc.setFontSize(7.2);
  doc.setTextColor(185, 28, 28);
  doc.text('NBA Accredited UG Programs: CSE, EEE, and MECH.', pageWidth / 2, 33.2, { align: 'center' });

  // 4. CSBS Department Logo Centered Beneath Institutional Heading
  const csbsLogo = certData.csbs_logo || (typeof window !== 'undefined' && window.CERT_ASSETS ? window.CERT_ASSETS.CSBS_LOGO : null);
  if (csbsLogo) {
    try {
      const csbsW = 48;
      const csbsH = csbsW / 4.251;
      const csbsX = (pageWidth - csbsW) / 2;
      const csbsY = 35.8;
      doc.addImage(csbsLogo, 'PNG', csbsX, csbsY, csbsW, csbsH);
    } catch (e) {
      console.warn('CSBS logo embed warning:', e);
    }
  }

  // 5. Certificate Title
  doc.setFont('times', 'bold');
  doc.setFontSize(20);
  doc.setTextColor(74, 21, 75);
  doc.text((certData.certificate_title || 'CERTIFICATE OF PARTICIPATION').toUpperCase(), pageWidth / 2, 54.5, { align: 'center' });

  // Helper for Ornamental floral divider matching reference:
  function drawArabesque(doc, cx, cy) {
    const purple = [88, 28, 135];
    const gold = [197, 155, 39];

    function drawDiamond(cx, cy, rx, ry, style = 'F') {
      doc.lines([
        [rx, ry],
        [-rx, ry],
        [-rx, -ry],
        [rx, -ry]
      ], cx - rx, cy, [1, 1], style, true);
    }

    // Center purple double diamond / diamond with inner dot
    doc.setDrawColor(purple[0], purple[1], purple[2]);
    doc.setFillColor(purple[0], purple[1], purple[2]);
    doc.setLineWidth(0.35);

    drawDiamond(cx, cy, 1.8, 2.2, 'S');

    doc.setFillColor(purple[0], purple[1], purple[2]);
    doc.circle(cx, cy, 0.45, 'F');

    // Left and right gold diamonds
    doc.setFillColor(gold[0], gold[1], gold[2]);
    doc.setDrawColor(gold[0], gold[1], gold[2]);
    drawDiamond(cx - 3.8, cy, 1.4, 1.4, 'F');
    drawDiamond(cx + 3.8, cy, 1.4, 1.4, 'F');

    // Horizontal purple lines
    doc.setDrawColor(purple[0], purple[1], purple[2]);
    doc.setLineWidth(0.35);
    doc.line(cx - 32, cy, cx - 6.2, cy);
    doc.line(cx + 6.2, cy, cx + 32, cy);

    // Terminal gold dots
    doc.setFillColor(gold[0], gold[1], gold[2]);
    doc.circle(cx - 32, cy, 0.55, 'F');
    doc.circle(cx + 32, cy, 0.55, 'F');
  }

  drawArabesque(doc, pageWidth / 2, 58.5);

  // 6. Recipient Section
  doc.setFont('times', 'normal');
  doc.setFontSize(10.5);
  doc.setTextColor(31, 41, 55);
  doc.text(certData.preamble || 'This certificate is presented to', pageWidth / 2, 66.0, { align: 'center' });

  const participantName = certData.participant_name || certData.student_name || 'Keerthana Mohan';
  doc.setFont('times', 'bolditalic');
  let nameSize = 25;
  if (participantName.length > 28) nameSize = 20;
  if (participantName.length > 38) nameSize = 16;
  doc.setFontSize(nameSize);
  doc.setTextColor(59, 7, 100);
  doc.text(participantName, pageWidth / 2, 77.0, { align: 'center' });

  drawArabesque(doc, pageWidth / 2, 81.5);

  // 7. Event Description Paragraph
  const pY = 89.0;
  const lineSpacing = 5.2;

  function renderStyledLine(doc, segments, y, spaceGap = 1.6) {
    const computed = segments.map(seg => {
      doc.setFont(seg.font, seg.style);
      doc.setFontSize(seg.size);
      const cleanText = sanitizePdfText(seg.text).trim();
      let w = doc.getTextWidth(cleanText);
      if (seg.font === 'times' && (seg.style === 'bold' || seg.style === 'bolditalic')) {
        w += 0.8;
      }
      return { ...seg, cleanText, width: w };
    });

    const totalGaps = (segments.length - 1) * spaceGap;
    let totalW = computed.reduce((sum, s) => sum + s.width, 0) + totalGaps;

    const maxAllowedWidth = 246;
    let effectiveGap = spaceGap;
    if (totalW > maxAllowedWidth) {
      const scaleFactor = maxAllowedWidth / totalW;
      effectiveGap = spaceGap * scaleFactor;
      computed.forEach(seg => {
        seg.size *= scaleFactor;
        doc.setFont(seg.font, seg.style);
        doc.setFontSize(seg.size);
        seg.width = doc.getTextWidth(seg.cleanText) + (seg.font === 'times' && (seg.style === 'bold' || seg.style === 'bolditalic') ? 0.6 : 0);
      });
      totalW = computed.reduce((sum, s) => sum + s.width, 0) + (segments.length - 1) * effectiveGap;
    }

    let curX = (pageWidth - totalW) / 2;
    computed.forEach((seg, i) => {
      doc.setFont(seg.font, seg.style);
      doc.setFontSize(seg.size);
      doc.setTextColor(seg.color[0], seg.color[1], seg.color[2]);
      doc.text(seg.cleanText, curX, y);
      curX += seg.width + (i < computed.length - 1 ? effectiveGap : 0);
    });
  }

  const cBlack = [31, 41, 55];
  const cPurple = [74, 21, 75];

  let collStr = (certData.college_name || 'Ramco Institute of Technology').replace(/,\s*Rajapalayam.*$/i, '').trim();
  let evName = (certData.event_name || 'Emerging Blockchain Technologies – Architectures, Applications and Research Perspectives').replace(/^["“”]/, '').replace(/["“”]$/, '').trim();
  let progTitle = certData.programme_title || 'One Week Short-Term Training Programme (STTP)';
  let deptStr = certData.department || 'Department of Computer Science and Business Systems';
  let datesStr = (certData.programme_dates || 'October 12, 2026, to October 18, 2026').replace(/\.$/, '') + '.';

  renderStyledLine(doc, [
    { text: 'for active and enthusiastic participation in the', font: 'times', style: 'normal', size: 9.2, color: cBlack },
    { text: progTitle, font: 'times', style: 'bold', size: 9.2, color: cPurple },
    { text: 'on', font: 'times', style: 'normal', size: 9.2, color: cBlack }
  ], pY);

  renderStyledLine(doc, [
    { text: '"' + evName + '",', font: 'times', style: 'bold', size: 9.4, color: cPurple },
    { text: 'organized', font: 'times', style: 'normal', size: 9.2, color: cBlack }
  ], pY + lineSpacing);

  renderStyledLine(doc, [
    { text: 'by the', font: 'times', style: 'normal', size: 9.2, color: cBlack },
    { text: deptStr, font: 'times', style: 'bold', size: 9.2, color: cPurple },
    { text: 'at', font: 'times', style: 'normal', size: 9.2, color: cBlack },
    { text: collStr + ',', font: 'times', style: 'bold', size: 9.2, color: cPurple }
  ], pY + lineSpacing * 2);

  renderStyledLine(doc, [
    { text: 'Rajapalayam from', font: 'times', style: 'normal', size: 9.2, color: cBlack },
    { text: datesStr, font: 'times', style: 'bold', size: 9.2, color: cPurple }
  ], pY + lineSpacing * 3);

  // 8. Signatures: Exactly Four Visual Groups with Vertical Gold Separators
  const sigLineY = 138.0;
  const purple = [88, 28, 135];
  const gold = [197, 155, 39];

  function renderSigBlock(doc, sigSrc, cx, name, title) {
    const asset = getSignatoryAsset(sigSrc);
    if (asset) {
      try {
        const props = doc.getImageProperties(asset);
        const maxW = 26;
        const maxH = 12;
        let w = maxW;
        let h = maxH;
        if (props && props.width && props.height) {
          const aspect = props.width / props.height;
          if (maxW / aspect <= maxH) {
            h = maxW / aspect;
          } else {
            w = maxH * aspect;
          }
        }
        doc.addImage(asset, 'PNG', cx - w / 2, sigLineY - h - 1, w, h);
      } catch (e) {
        console.warn('Sig render warning for', name, e);
      }
    }

    // Baseline Line
    doc.setDrawColor(purple[0], purple[1], purple[2]);
    doc.setLineWidth(0.35);
    doc.line(cx - 13, sigLineY, cx + 13, sigLineY);

    // Name
    doc.setFont('times', 'bold');
    doc.setFontSize(8.2);
    doc.setTextColor(17, 24, 39);
    doc.text(name, cx, sigLineY + 4.5, { align: 'center' });

    // Optional individual title
    if (title) {
      doc.setFont('times', 'bold');
      doc.setFontSize(8.5);
      doc.setTextColor(74, 21, 75);
      doc.text(title, cx, sigLineY + 9.5, { align: 'center' });
    }
  }

  function drawVerticalSep(x) {
    doc.setDrawColor(gold[0], gold[1], gold[2]);
    doc.setLineWidth(0.35);
    doc.line(x, 132.0, x, 149.0);
  }

  // Group 1: Faculty Coordinators (3 blocks)
  renderSigBlock(doc, certData.signatory_1_sig || certData.signatory_1_name || 'jeyasundari', 32, certData.signatory_1_name || 'Dr. M. Jeya Sundari');
  renderSigBlock(doc, certData.signatory_2_sig || certData.signatory_2_name || 'rekha', 66, certData.signatory_2_name || 'M. Rekha');
  renderSigBlock(doc, certData.signatory_3_sig || certData.signatory_3_name || 'ramakrishnan', 100, certData.signatory_3_name || 'M. Ramakrishnan');

  doc.setFont('times', 'bold');
  doc.setFontSize(9.0);
  doc.setTextColor(74, 21, 75);
  doc.text('Faculty Coordinators', 66, sigLineY + 12.0, { align: 'center' });

  // Separator 1
  drawVerticalSep(119);

  // Group 2: Convenor
  const cxConvenor = 143;
  renderSigBlock(doc, certData.signatory_4_sig || certData.signatory_4_name || 'kesavaraja', cxConvenor, certData.signatory_4_name || 'Dr. D. Kesavaraja', 'Convenor');

  // Separator 2
  drawVerticalSep(168);

  // Group 3: Patron
  const cxPatron = 192;
  renderSigBlock(doc, certData.signatory_5_sig || certData.signatory_5_name || 'rajakarunakaran', cxPatron, certData.signatory_5_name || 'Dr. S. Rajakarunakaran', 'Patron');

  // Separator 3
  drawVerticalSep(217);

  // Group 4: Chief Patron
  const cxChiefPatron = 241;
  renderSigBlock(doc, certData.signatory_6_sig || certData.signatory_6_name || 'ganesan', cxChiefPatron, certData.signatory_6_name || 'Dr. L. Ganesan', 'Chief Patron');

  // Separator 4
  drawVerticalSep(265);

  // 9. Dedicated QR Code in Bottom Right Area
  const certId = certData.certificate_number || certData.certificate_id || 'RIT-STTP-2026-0001';
  const qrTarget = certData.verification_url || ((typeof window !== 'undefined' && window.location && window.location.origin) ? window.location.origin : 'https://rit-csbs-portal.vercel.app') + '/verify-certificate.html?id=' + encodeURIComponent(certId);

  let qrDataUrl = null;
  if (typeof document !== 'undefined' && typeof QRCode !== 'undefined' && QRCode.toDataURL) {
    try {
      qrDataUrl = await QRCode.toDataURL(qrTarget, { margin: 1, width: 140, color: { dark: '#1E1B4B', light: '#FFFFFF' } });
    } catch (e) {}
  }
  if (!qrDataUrl && typeof require !== 'undefined') {
    try {
      const nodeQr = require('qrcode');
      qrDataUrl = await nodeQr.toDataURL(qrTarget, { margin: 1, width: 140, color: { dark: '#1E1B4B', light: '#FFFFFF' } });
    } catch (e) {}
  }

  if (qrDataUrl) {
    try {
      doc.addImage(qrDataUrl, 'PNG', 270, 151, 19, 19);
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(5.5);
      doc.setTextColor(74, 21, 75);
      doc.text('SCAN TO VERIFY', 279.5, 173.5, { align: 'center' });
    } catch (e) {
      console.warn('PDF QR embed error:', e);
    }
  }

  // 10. Unique Certificate ID in Centered Rounded Pill with Flanking Gold Lines & Diamonds
  const pillW = 68;
  const pillH = 6.8;
  const pillX = (pageWidth - pillW) / 2;
  const pillY = 173.0;

  const lineLen = 32;
  const leftLineStartX = pillX - lineLen - 4;
  const leftLineEndX = pillX - 3;
  const rightLineStartX = pillX + pillW + 3;
  const rightLineEndX = pillX + pillW + lineLen + 4;

  doc.setDrawColor(gold[0], gold[1], gold[2]);
  doc.setFillColor(gold[0], gold[1], gold[2]);
  doc.setLineWidth(0.35);

  // Left line + dot + diamond
  doc.line(leftLineStartX, pillY + pillH / 2, leftLineEndX, pillY + pillH / 2);
  doc.circle(leftLineStartX, pillY + pillH / 2, 0.55, 'F');
  const lMidX = (leftLineStartX + leftLineEndX) / 2;
  doc.lines([[1.2, 1.2], [-1.2, 1.2], [-1.2, -1.2], [1.2, -1.2]], lMidX - 1.2, pillY + pillH / 2, [1, 1], 'F', true);

  // Right line + dot + diamond
  doc.line(rightLineStartX, pillY + pillH / 2, rightLineEndX, pillY + pillH / 2);
  doc.circle(rightLineEndX, pillY + pillH / 2, 0.55, 'F');
  const rMidX = (rightLineStartX + rightLineEndX) / 2;
  doc.lines([[1.2, 1.2], [-1.2, 1.2], [-1.2, -1.2], [1.2, -1.2]], rMidX - 1.2, pillY + pillH / 2, [1, 1], 'F', true);

  // Rounded Pill
  doc.setFillColor(255, 255, 255);
  doc.roundedRect(pillX, pillY, pillW, pillH, 3.4, 3.4, 'FD');

  // Text inside pill
  doc.setFont('times', 'bold');
  doc.setFontSize(8.2);
  doc.setTextColor(26, 26, 64);
  doc.text(`Certificate ID: ${certId}`, pageWidth / 2, pillY + 4.8, { align: 'center' });

  return doc;
}


window.RIT_CERT_ASSETS = {
  ...window.CERT_ASSETS,
  drawCertificate: drawRitCertificate,
  createCertificatePdf: createCertificatePdf,
  loadImage: ritLoadImage,
  renderQrCode: ritRenderQrCode,
  getSignatoryAsset: getSignatoryAsset
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    ...window.RIT_CERT_ASSETS,
    drawRitCertificate,
    createCertificatePdf,
    getSignatoryAsset
  };
}
